#!/usr/bin/env python3
from __future__ import annotations
import html, json, sqlite3
from collections import Counter
from pathlib import Path

ROOT=Path('/root/werkraum/_gpt/gesamtatlas/endproduktbeweis')
UI=ROOT/'UI'
DB=ROOT/'ANFORDERUNGEN/ANFORDERUNGSREGISTER.sqlite'
INTEGRATION=ROOT/'INTEGRATION'
UI.mkdir(parents=True,exist_ok=True)
connection=sqlite3.connect(f'file:{DB}?mode=ro',uri=True); connection.row_factory=sqlite3.Row
requirements=[]
for row in connection.execute('select * from requirements order by category,id'):
    item=dict(row)
    for key in ('implementation_paths_json','technical_test_ids_json','playwright_test_ids_json'):
        item[key[:-5]]=json.loads(item.pop(key))
    requirements.append(item)
connection.close()
status=json.loads((INTEGRATION/'STATUS.json').read_text())
tasks=json.loads((INTEGRATION/'LLM_ABNAHME_AUFGABEN.json').read_text())
effect_status=json.loads((ROOT/'WIRKUNG/STATUS.json').read_text())
effect_example=json.loads((ROOT/'WIRKUNG/BEISPIEL_ORIGINALVERLAUF.json').read_text())
terminal_status=json.loads((ROOT/'TERMINALWIRKUNG/STATUS.json').read_text())
terminal_chain=json.loads((ROOT/'TERMINALWIRKUNG/BEISPIEL_PLAYWRIGHT_KORREKTUR.json').read_text())
time_status=json.loads((ROOT/'ZEITREISE/STATUS.json').read_text())
time_moment=json.loads((ROOT/'ZEITREISE/BEISPIEL_MOMENT_203015.json').read_text())
counts=Counter(r['current_implementation_status'] for r in requirements)
payload={'requirements':requirements,'integration':status,'tasks':tasks,'effect':effect_status,'terminal_effect':terminal_status,'epistemic_time':time_status,'status_counts':dict(counts)}
(UI/'DATA.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2,sort_keys=True)+'\n',encoding='utf-8')
css='''
:root{color-scheme:dark;--bg:#0c0812;--panel:#181020;--panel2:#21152d;--ink:#f6edfb;--muted:#c9b7d6;--line:#503d61;--accent:#d3a6ff;--red:#ff9b9b;--amber:#ffd48c;--green:#9de4bd}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#2a173d,#0c0812 50%);color:var(--ink);font:16px/1.5 system-ui,sans-serif}header,main,footer{max-width:1220px;margin:auto;padding:1rem}h1{font-size:clamp(2.5rem,7vw,5rem);line-height:.98;margin:.4rem 0 1rem}a{color:#e1c1ff}.muted{color:var(--muted)}.hero{padding:2.5rem 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}.card,.panel{background:linear-gradient(145deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:18px;padding:1rem;min-width:0;overflow-wrap:anywhere;word-break:break-word}.grid>*{min-width:0}.number{font-size:2rem;font-weight:800;color:var(--accent)}.red{color:var(--red)}.amber{color:var(--amber)}.green{color:var(--green)}.controls{display:grid;grid-template-columns:2fr 1fr;gap:.7rem;margin:1rem 0}input,select{width:100%;padding:.8rem;border:1px solid var(--line);border-radius:12px;background:#0b0710;color:var(--ink)}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{text-align:left;padding:.55rem;border-bottom:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere;word-break:break-word}.status{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:.15rem .5rem;overflow-wrap:anywhere}.rowbutton{background:none;border:0;color:var(--accent);text-align:left;padding:0;cursor:pointer;font:inherit}.detail{white-space:pre-wrap;overflow-wrap:anywhere;max-height:40rem;overflow:auto}.workflow{display:flex;gap:.4rem;flex-wrap:wrap}.workflow span{border:1px solid var(--line);border-radius:999px;padding:.35rem .6rem}.notice{border-left:4px solid var(--red);padding:1rem;background:#251418;border-radius:10px}.hidden{display:none}@media(max-width:680px){body{font-size:14px}.controls{grid-template-columns:1fr}th:nth-child(3),td:nth-child(3){display:none}header,main,footer{padding:.7rem}}
'''
js='''
const D=window.__DATA__;const tbody=document.querySelector('#rows'),q=document.querySelector('#q'),filter=document.querySelector('#filter'),detail=document.querySelector('#detail');
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function cls(s){if(/not_|blocked|open_|pending/.test(s))return'red';if(/partial|revalidation|contract_/.test(s))return'amber';return'green'}
function render(){const needle=q.value.trim().toLowerCase(),state=filter.value;const rows=D.requirements.filter(r=>(!state||r.current_implementation_status===state)&&(!needle||(r.id+' '+r.title+' '+r.requirement_summary+' '+r.category).toLowerCase().includes(needle)));tbody.innerHTML=rows.map(r=>`<tr><td><button class="rowbutton" data-id="${esc(r.id)}">${esc(r.id)}</button></td><td>${esc(r.title)}</td><td>${esc(r.category)}</td><td><span class="status ${cls(r.current_implementation_status)}">${esc(r.current_implementation_status)}</span></td></tr>`).join('');document.querySelector('#visible').textContent=rows.length;document.querySelectorAll('.rowbutton').forEach(b=>b.addEventListener('click',()=>show(b.dataset.id)))}
function show(id){const r=D.requirements.find(x=>x.id===id);detail.classList.remove('hidden');detail.innerHTML=`<h2>${esc(r.id)} · ${esc(r.title)}</h2><p><span class="status ${cls(r.current_implementation_status)}">${esc(r.current_implementation_status)}</span></p><p>${esc(r.requirement_summary)}</p><p><strong>Quelle:</strong> ${esc(r.source_path)} · Zeilen ${r.source_start}–${r.source_end}</p><h3>Originalausschnitt</h3><div class="detail">${esc(r.source_excerpt)}</div><h3>Umsetzungspfade</h3><div class="detail">${esc((r.implementation_paths||[]).join(String.fromCharCode(10))||'Noch keiner')}</div>`;detail.scrollIntoView({behavior:'smooth',block:'start'})}
q.addEventListener('input',render);filter.addEventListener('change',render);render();
'''
states=''.join(f'<option value="{html.escape(k)}">{html.escape(k)} ({v})</option>' for k,v in sorted(counts.items()))
workflow=['DISTRIBUTED','READING_RESPONSE_RAW','ASSESSED','PROPOSED_NOT_CANONICAL','DANIEL_APPROVED','IMPLEMENTED_UNVERIFIED','VALIDATED','CANONICAL']
cards=f'''<section class="grid"><article class="card"><div class="number">{len(requirements)}</div><p>Anforderungs-IDs</p></article><article class="card"><div class="number red">{sum(1 for r in requirements if any(x in r['current_implementation_status'] for x in ('not_','blocked','open_','pending')))}</div><p>offen oder blockiert</p></article><article class="card"><div class="number">{status.get('raw_response_count',0)}</div><p>reale Fremdantworten</p></article><article class="card"><div class="number">{status.get('canonical_count',0)}</div><p>kanonisch integrierte Vorschläge</p></article></section>'''
body=f'''<section class="hero"><p class="muted">quellengebundener Erfüllungsvertrag</p><h1>Nichts ist fertig, nur weil es <span style="color:var(--accent)">überzeugend klingt.</span></h1><p>Jede Anforderung besitzt Quelle, Status, Bauteil und eigene Beweise. Die Browser-Erweiterung bleibt bis zur realen Aktivierung sichtbar offen.</p></section>{cards}<section class="notice"><strong>Browser-Realabnahme offen:</strong> Der Recorder wird separat buggefixt. Kein Browserorgan wird hier heimlich grüngezählt.</section><section class="panel"><h2>Integrationsschranke</h2><div class="workflow">{''.join(f'<span>{s}</span>' for s in workflow)}</div><p>Nur Daniel darf die Übergänge zu <code>DANIEL_APPROVED</code> und endgültig <code>CANONICAL</code> bestätigen.</p></section><section><h2>Anforderungsmatrix</h2><div class="controls"><input id="q" placeholder="ID, Titel oder Begriff suchen"><select id="filter"><option value="">alle Statusklassen</option>{states}</select></div><p><span id="visible">0</span> sichtbare Anforderungen</p><div class="panel"><table><thead><tr><th>ID</th><th>Anforderung</th><th>Kategorie</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table></div></section><section id="detail" class="panel hidden"></section>'''
page=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gesamtatlas-Endproduktbeweis</title><style>{css}</style></head><body><header><a href="../00_BEWEIS_START.md">Beweisstart</a> · <a href="../ANFORDERUNGEN/ANFORDERUNGSREGISTER.sqlite">SQLite</a> · <a href="../INTEGRATION/LLM_ABNAHME_AUFGABEN.json">Fremdtest</a> · <a href="wirkung.html">Wirkungsstufen</a> · <a href="terminalwirkung.html">Terminalwirkung</a> · <a href="zeitreise.html">Zeitreise</a></header><main>{body}</main><footer><p class="muted">Private lokale Beweisoberfläche. Keine öffentliche Gesamtatlasroute.</p></footer><script>window.__DATA__={json.dumps(payload,ensure_ascii=False).replace('</','<\\/')}</script><script>{js}</script></body></html>'''
(UI/'index.html').write_text(page,encoding='utf-8')
stage_cards=[]
for stage in effect_example['stages']:
    status_class='green' if stage['effective_status']=='BEWIESEN' else ('red' if stage['effective_status'] in {'WIDERLEGT','WIDERSPRUECHLICH'} else 'amber')
    stage_cards.append(f'''<article class="card evidence-stage" data-stage="{html.escape(stage['stage'])}" data-status="{html.escape(stage['effective_status'])}"><h2>{html.escape(stage['stage'])}</h2><p class="number {status_class}">{html.escape(stage['effective_status'])}</p><p>{html.escape(stage['explanation'])}</p><p class="muted">Eigene Belege: {stage['sufficient_evidence_count']}</p></article>''')
transition_rows=''.join(f'''<tr data-transition="{html.escape(t['from_stage'])}-{html.escape(t['to_stage'])}"><td>{html.escape(t['from_stage'])}</td><td>{html.escape(t['to_stage'])}</td><td><span class="status {'green' if t['status']=='DIRECTLY_EVIDENCED' else 'amber'}">{html.escape(t['status'])}</span></td><td>{html.escape(t['reason'])}</td></tr>''' for t in effect_example['transitions'])
wirkung_body=f'''<section class="hero"><p class="muted">GA-EVIDENCE-006 · reales Produktionsbeispiel</p><h1>Existenz ist <span style="color:var(--accent)">kein Lesen.</span></h1><p>Jede Informationsstufe braucht ihren eigenen Beleg. Frühere Stufen werden niemals nach oben vererbt.</p></section><section class="grid">{''.join(stage_cards)}</section><section class="panel"><h2>Übergänge</h2><table><thead><tr><th>Von</th><th>Zu</th><th>Status</th><th>Begründung</th></tr></thead><tbody>{transition_rows}</tbody></table></section><section class="notice"><strong>Bewusst unbekannt:</strong> Für den nachgereichten Verlauf sind Anzeige, Lesen, Verwendung und Handlungswirkung in diesem Organ noch nicht eigenständig belegt. Der Atlas füllt diese Lücke nicht mit Persönlichkeit.</section><p><a href="../WIRKUNG/WIRKUNGSSTUFEN.sqlite">SQLite-Datenmodell</a> · <a href="../WIRKUNG/STATUS.json">Maschinenstatus</a> · <a href="index.html">zur Anforderungsmatrix</a></p>'''
wirkung_page=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wirkungsstufen · Gesamtatlas-Endproduktbeweis</title><style>{css}</style></head><body><header><a href="index.html">Anforderungen</a> · <a href="../WIRKUNG/README.md">Vertrag</a></header><main>{wirkung_body}</main><footer><p class="muted">Sechs getrennte Beweisstufen. Keine automatische Wirkungserzählung.</p></footer></body></html>'''
(UI/'wirkung.html').write_text(wirkung_page,encoding='utf-8')
node_cards=[]
for node in terminal_chain['nodes']:
    status_class='red' if node['node_type']=='LUECKE' else ('amber' if node['status']=='UNBEKANNT' else 'green')
    extra=f'''<p class="muted">{html.escape(node.get('gap_reason') or node.get('source_ref') or 'ohne Quelle')}</p>'''
    node_cards.append(f'''<article class="card chain-node" data-node-type="{html.escape(node['node_type'])}" data-status="{html.escape(node['status'])}"><p class="muted">{node['position']}</p><h2>{html.escape(node['node_type'])}</h2><p class="{status_class}">{html.escape(node['label'])}</p>{extra}</article>''')
link_rows=''.join(f'''<tr class="chain-link" data-link-class="{html.escape(link['relation_class'])}" data-causal="{link['causal_claim']}"><td>{html.escape(link['relation'])}</td><td><span class="status {'green' if link['relation_class'] in {'EXPLICIT_PARENT_EVENT','COMMON_ARTIFACT_SUPPORTED'} else 'amber'}">{html.escape(link['relation_class'])}</span></td><td>{html.escape(link['explanation'])}</td></tr>''' for link in terminal_chain['links'])
terminal_body=f'''<section class="hero"><p class="muted">GA-TERMINAL-034 · reales Produktionsbeispiel</p><h1>Eine Reihenfolge ist noch <span style="color:var(--accent)">keine Ursache.</span></h1><p>Die Kette zeigt Impuls, Entscheidung, Werkzeug, Artefakt, Test, Korrektur und Folge. Der nicht erhaltene Interpretationsschritt bleibt sichtbar rot.</p></section><section class="grid">{''.join(node_cards)}</section><section class="panel"><h2>Beziehungen</h2><table><thead><tr><th>Relation</th><th>Wahrheitsklasse</th><th>Begründung</th></tr></thead><tbody>{link_rows}</tbody></table></section><section class="grid"><article class="card"><div class="number">{terminal_status['history_event_count']}</div><p>importierte History-Ereignisse</p></article><article class="card"><div class="number amber">{terminal_status['automatic_correction_candidates']}</div><p>automatische Kandidaten, keine Beweise</p></article><article class="card"><div class="number red">{terminal_status['history_parent_event_count']}</div><p>explizite Parent-Kausalbelege</p></article><article class="card"><div class="number red">{terminal_status['gap_count']}</div><p>sichtbare Kettenlücke</p></article></section><section class="notice"><strong>{html.escape(terminal_status['production_chain_status'])}:</strong> {html.escape(terminal_status['truth_boundary'])}</section><p><a href="../TERMINALWIRKUNG/WIRKUNGSKETTEN.sqlite">SQLite-Datenbank</a> · <a href="../TERMINALWIRKUNG/BEISPIEL_PLAYWRIGHT_KORREKTUR.json">Maschinenansicht</a> · <a href="index.html">zur Matrix</a></p>'''
terminal_page=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Terminalwirkung · Gesamtatlas-Endproduktbeweis</title><style>{css}</style></head><body><header><a href="index.html">Anforderungen</a> · <a href="wirkung.html">Wirkungsstufen</a></header><main>{terminal_body}</main><footer><p class="muted">Artefaktgestützte Teilkette. Keine erfundene Kausalität.</p></footer></body></html>'''
(UI/'terminalwirkung.html').write_text(terminal_page,encoding='utf-8')
time_item_cards=[]
for item in time_moment['items']:
    state_html=''.join(f'''<li data-state="{html.escape(st['state'])}" data-status="{html.escape(st['effective_status'])}"><strong>{html.escape(st['state'])}</strong>: <span class="{'green' if st['effective_status']=='BEWIESEN' else 'amber'}">{html.escape(st['effective_status'])}</span></li>''' for st in item['states'])
    time_item_cards.append(f'''<article class="card time-item" data-item-id="{html.escape(item['item_id'])}"><h2>{html.escape(item['label'])}</h2><ul>{state_html}</ul><p class="muted">{html.escape(item.get('source_path') or item['object_ref'])}</p></article>''')
context_rows=''.join(f'''<tr class="time-context" data-context-type="{html.escape(ctx['context_type'])}"><td>{html.escape(ctx['timestamp_utc'])}</td><td>{html.escape(ctx['context_type'])}</td><td>{html.escape(ctx['action'] or '')}</td><td>{html.escape(ctx['event_status'] or '')}</td></tr>''' for ctx in time_moment['technical_context'])
retro_cards=''.join(f'''<article class="card retrospective" data-learned-utc="{html.escape(r['learned_utc'])}"><p class="muted">erst später · {html.escape(r['learned_utc'])}</p><h2>{html.escape(r['label'])}</h2><p>{html.escape(r['statement'])}</p></article>''' for r in time_moment['retrospective_meaning'])
time_body=f'''<section class="hero"><p class="muted">GA-TIME-011 · Moment {html.escape(time_status['at_utc'])}</p><h1>Damals wusste das System <span style="color:var(--accent)">nicht, was später kam.</span></h1><p>Technischer Kontext, attestierte Informationszustände und spätere Bedeutung bleiben drei getrennte Schichten.</p></section><section class="grid">{''.join(time_item_cards)}</section><section class="panel"><h2>Technischer Kontext bis zum Anchor</h2><p>{time_status['technical_context_count']} Ereignisse aus derselben Session, kein Ereignis danach.</p><div style="max-height:32rem;overflow:auto"><table><thead><tr><th>Zeit</th><th>Typ</th><th>Aktion</th><th>Status</th></tr></thead><tbody>{context_rows}</tbody></table></div></section><section><h2>Spätere Bedeutung, nicht damaliges Wissen</h2><div class="grid">{retro_cards}</div></section><section class="notice"><strong>{html.escape(time_status['completeness_status'])}:</strong> {html.escape(time_status['truth_boundary'])}</section><p><a href="../ZEITREISE/EPISTEMISCHE_MOMENTE.sqlite">SQLite-Datenbank</a> · <a href="../ZEITREISE/BEISPIEL_MOMENT_203015.json">Maschinenansicht</a> · <a href="index.html">zur Matrix</a></p>'''
time_page=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Epistemische Zeitreise · Gesamtatlas-Endproduktbeweis</title><style>{css}</style></head><body><header><a href="index.html">Anforderungen</a> · <a href="wirkung.html">Wirkungsstufen</a> · <a href="terminalwirkung.html">Terminalwirkung</a></header><main>{time_body}</main><footer><p class="muted">Spätere Erkenntnis wird nicht rückwirkend zum damaligen Wissen.</p></footer></body></html>'''
(UI/'zeitreise.html').write_text(time_page,encoding='utf-8')
(UI/'STATUS.json').write_text(json.dumps({'ok':True,'requirements':len(requirements),'browser_blocked_visible':True,'integration_states':workflow,'evidence_stages':6,'effect_example_object':effect_status['example_object'],'terminal_chain_id':terminal_status['production_chain_id'],'terminal_chain_status':terminal_status['production_chain_status'],'epistemic_moment_id':time_status['moment_id'],'epistemic_moment_status':time_status['completeness_status'],'private_only':True},ensure_ascii=False,indent=2,sort_keys=True)+'\n',encoding='utf-8')
print(json.dumps({'ok':True,'ui':str(UI/'index.html'),'wirkung_ui':str(UI/'wirkung.html'),'terminalwirkung_ui':str(UI/'terminalwirkung.html'),'zeitreise_ui':str(UI/'zeitreise.html'),'requirements':len(requirements)},ensure_ascii=False))
